args.sql:
SELECT COUNT(*) FROM (
    SELECT DISTINCT cl."CLSTR_PIN", cl."NetInfl"
    FROM cluster_analysis cl
    WHERE cl."NetInfl" > 0.8
) sub;

SELECT COUNT(*) FROM (
    SELECT DISTINCT rm.acct_risk
    FROM risk_and_moderation rm
    WHERE (rm.risk_profile->'risk_scores'->>'impact_score')::numeric > 0.8
) sub;

SELECT COUNT(*) FROM (
    SELECT DISTINCT cl."CLSTR_PIN"
    FROM cluster_analysis cl
    JOIN account_clusters ac ON cl."CLSTR_PIN" = ac.clu_ref
    WHERE cl."NetInfl" > 0.8
) sub;

SELECT COUNT(*) FROM (
    SELECT DISTINCT nm.acct_node
    FROM network_metrics nm
    WHERE nm."FollowNum" > 1000
) sub;

SELECT COUNT(DISTINCT a.acct_ref) FROM accounts a WHERE EXISTS (
    SELECT 1 FROM content_activity ca 
    WHERE ca.acct_slot = a.acct_ref 
    AND (ca.content_metrics->'posting'->>'posts_per_day')::numeric > 30
) AND EXISTS (
    SELECT 1 FROM account_clusters ac 
    JOIN cluster_analysis cl ON ac.clu_ref = cl."CLSTR_PIN" 
    WHERE ac.acct_bridge = a.acct_ref 
    AND cl."NetInfl" > 0.8
);
